    function tfConfig(owner, repo) {
        return { fileMap: { '../.dmtools/config.js':
            'module.exports = { repository: { owner: "' + owner + '", repo: "' + repo + '" } };' } };
    }

    function sha40(n) {
        var s = 'abc' + n;
        while (s.length < 40) s += '0';
        return s;
    }

