    test('an issue-carrier dispatch failure records nothing (parking is PR-carrier only)', function () {
        var sm = makeSmAgent(Object.assign(tfConfig('o', 'r'), {
            captureConsole: true,
            github: {
                items: [{ key: 'gh-5', labels: ['agent:rework'], issueNumber: 5,
