            capturedTriggers.push({ owner: owner, repo: repo, workflow: workflow, inputs: inputs, ref: ref });
            if (opts.onTrigger) opts.onTrigger(owner, repo, workflow, inputs, ref);
        },
        listPrs: function() { return '[]'; },
