        var vProbe = vHead0 ? probeDispatchedState(effectiveRepoInfo, vCiWf, vHead0) : null;
        if (vProbe && vProbe.active) {
            console.log('  ⏭️  ' + key +
                        ' validation already dispatching on this head — skip');
