                tfPr(302, ['agent:review', 'priority_blocker'], DEAD_REF), // younger blocker, DEAD head
                tfPr(301, ['agent:review'], 'feat/alive')                  // older medium, live head
            ]) },
            onTrigger: function (o, r, w, inputs, ref) {
