        // park-reset rule (no mergeState guard → no lazy head sha) —
        // resolve the head before probing.
        var vprHead = resolveHeadSha(effectiveRepoInfo, ticket);
        var vprActor = parkResetCommit(effectiveRepoInfo, vprHead, vprMachineLogin);
        var vprParkedAt = parkedSince(effectiveRepoInfo, ticket.prNumber);
        var vprActorLogin = ((vprActor && vprActor.login) || '').toLowerCase();
        // gh-728: the knob is a login LIST — any entry's push is
        // machine movement and never clears the park.
        var vprMachinePush = String((vprActor && vprActor.committer) || '') === 'sm-silent-update' ||
            machineAuthorModule.isMachineLogin(vprActorLogin, vprMachineLogin);
        var vprFreshPush = !!(vprActor && vprActor.date && vprParkedAt &&
            Date.parse(vprActor.date) > Date.parse(vprParkedAt));
        if (vprActor !== null && vprParkedAt !== null && vprFreshPush && !vprMachinePush) {
            if (!DRY) {
                try {
                    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).removeLabel(ticket.prNumber, 'validation_failed');
                } catch (eVfClr) {
                    console.warn('  ⚠️  un-park label failed: ' + (eVfClr.message || eVfClr));
                }
                try {
                    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(ticket.prNumber, '🅿️→▶ validation_failed cleared — human push by `' + (vprActorLogin || 'unknown') + '` at ' + vprActor.date + ' (last substantive commit `' + (vprActor.sha || vprHead) + '` of head `' + vprHead + '`, machine merges of main walked past — #681)' + ' is newer than the park (' + vprParkedAt + '). Re-entering validation (update_branch RESET never ' + 'ran: the head is not BEHIND — live fa 2026-10-03).');
                } catch (eVfSay) {}
            }
            console.log('  ▶ ' + key + ' park cleared (fresh human push) — validation proceeds');
        } else {
            console.log('  ⏭️  ' + key + ' validation_failed — parked; NO validation CI' +
                        ' until a HUMAN push newer than the park clears it');
            continue;
        }
    }
    if (!ticket.branch) {
