    var capturedScmConfigs = [];
    var capturedIoCacheDrops = [];
    var capturedLogs = [];

    // Controlled file_read: config discovery paths from fileMap only; other paths from disk.
    var fileReadMock = function(readOpts) {
        var p = readOpts.path;
