        assert.ok(logs.some(function (l) {
            return l.indexOf('\uD83E\uDD47') !== -1 && l.indexOf('pr-302') !== -1;
        }), 'the blocker taking the limit:1 slot over a cut medium still logs the preemption line');
    });
});

