        if (p.indexOf('agents/') === 0) {
            try { return file_read({ path: p.substring('agents/'.length) }); } catch (e) {}
        }
        return null;
    };

    var jiraSearchMock = function(searchOpts) {
        capturedJqls.push(searchOpts.jql);
        return opts.tickets || [];
    };

    var smMocks = {
        file_read: fileReadMock,
