        var deadPr = tfPr(302, ['agent:review', 'agent:rework', 'priority_blocker'], DEAD_REF);
        function twoRules() {
            return [
                { source: 'github', id: 'review-on-label-gh922',
                  query: { type: 'pr', labels: ['agent:review'], draft: false },
                  inputs: { pr: '{prNumber}', leg: 'review' },
