73:
74:/**
75: * Aggregate marker lines over comment bodies → { <branch>: <max N> }.
76: * Malformed lines and other branches' markers are ignored; the highest
77: * attempt number wins (duplicate markers never inflate the count).
78: */
79:function triggerFailMarks(bodies) {
80:    var map = {};
81:    (bodies || []).forEach(function (body) {
82:        var s = String(body == null ? '' : body);
83:        TRIGGER_FAIL_MARKER_RE.lastIndex = 0;
84:        var m;
85:        while ((m = TRIGGER_FAIL_MARKER_RE.exec(s)) !== null) {
86:            var branch = m[1];
87:            var n = parseInt(m[2], 10) || 0;
88:            if (n > (map[branch] || 0)) map[branch] = n;
89:        }
90:    });
91:    return map;
92:}
