94:/**
95: * The marker line for THIS failure (count = prior + 1 — the caller holds
96: * the already-read marks; no second comment fetch).
97: */
98:function triggerFailMarkerLine(count, branch, cap, atIso) {
99:    return '\u26A0\uFE0F trigger-failed ' + branch +
100:        ' \u2014 attempt ' + count + '/' + cap + ' at ' + (atIso || '');
101:}
102:
103:/**
104: * The dead-head park threshold: 3 consecutive no-ref failures on one head
105: * (gh-922 ask 3, "suggest 3"). jobParams.triggerFailParkCap tunes it per
106: * deployment; 0 / negative / 'false' disables the marker+park bookkeeping
107: * (the engine's fail-open slot yield is independent of this cap).
108: */
109:function capOf(jobParams) {
110:    var raw = (jobParams || {}).triggerFailParkCap;
