    test('github: branchExists — snapshot hit, #639 probe hit, and genuinely gone', function () {
        // gh-922: the dead-head park bench asks the provider whether a
        // parked PR's head ref still exists.
        var probeCmds = [];
        var p = loadProvider('github', {
            github_list_branches: function () {
                return [{ name: 'main', commit: { sha: 'm' }];  // page 1 only
            },
            cli_execute_command: function (args) {
                probeCmds.push(args.command);
                if (args.command.indexOf('/branches/off-page') !== -1) return 'aa11bb22cc33dd44ee55ff66aa77bb88cc99dd00';
                if (args.command.indexOf('/branches/gone') !== -1) throw new Error('404 Not Found');
                return '';
            }
        });
        assert.equal(p.branchExists('main'), true, 'a page-1 branch is found without any probe');
        assert.equal(probeCmds.length, 0);
        assert.equal(p.branchExists('off-page'), true, 'the #639 single-branch probe rescues a page-1 miss');
        assert.equal(p.branchExists('gone'), false, 'a 404 probe → the ref is gone → bench');
        assert.equal(p.branchExists(''), false, 'an empty ref fails closed (nothing to dispatch against)');
