            captureConsole: true,
            github: { items: function () {
                return [stubPr(302, ['agent:review', 'agent:rework', 'priority_blocker'], DEAD_REF)];
            }, prComments: [] },
            onTrigger: function () { throw new Error(NO_REF_ERR); }
        }));
